files.content:
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1c1526;
  --color-panel: #2e233d;
  --color-panel-border: #4d3b66;
  --color-gold: #ffbe2e;
  --color-gold-dark: #cc8e14;
  --color-text: #f5edfc;
  --color-muted: #ab9cb8;
  --color-btn: #412f57;
  --color-btn-hover: #583f77;
  --color-btn-active: #2c1e3d;
  --color-btn-disabled: #231b2d;
  --color-disabled-text: #675c73;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Courier New", Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  line-height: 1.4;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-bg);
  color: var(--color-text);
  padding: 16px;
}

.miner-card {
  background-color: var(--color-panel);
  border: 4px solid var(--color-panel-border);
  box-shadow: 0 10px 0 #0d0a14;
  border-radius: 4px;
  width: 100%;
  max-width: 400px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.miner-header {
  text-align: center;
}

.miner-title {
  font-size: 24px;
  color: var(--color-gold);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

.miner-subtitle {
  font-size: 14px;
  color: var(--color-muted);
}

.canvas-container {
  display: flex;
  justify-content: center;
  background: #150f1d;
  border: 2px solid var(--color-panel-border);
  padding: 8px;
  border-radius: 4px;
}

#mine-canvas {
  image-rendering: pixelated;
  background: #110d17;
  max-width: 100%;
  height: auto;
}

.stats-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.stat-box {
  background: #1f182c;
  border: 2px solid var(--color-panel-border);
  padding: 12px 8px;
  text-align: center;
  border-radius: 4px;
}

.stat-label {
  display: block;
  font-size: 14px;
  color: var(--color-muted);
  margin-bottom: 4px;
  text-transform: uppercase;
}

.stat-value {
  font-size: 22px;
  font-weight: bold;
  color: var(--color-gold);
}

.actions-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pixel-btn {
  appearance: none;
  background-color: var(--color-btn);
  color: var(--color-text);
  border: 3px solid var(--color-gold);
  border-radius: 4px;
  padding: 12px 16px;
  cursor: pointer;
  font-family: inherit;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  box-shadow: 0 4px 0 var(--color-gold-dark);
  transition: background-color 0.1s, transform 0.1s, box-shadow 0.1s;
}

.pixel-btn:hover:not(:disabled) {
  background-color: var(--color-btn-hover);
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--color-gold);
  outline-offset: 4px;
}

.pixel-btn:active:not(:disabled) {
  transform: translateY(4px);
  box-shadow: 0 0 0 var(--color-gold-dark);
  background-color: var(--color-btn-active);
}

.pixel-btn:disabled {
  background-color: var(--color-btn-disabled);
  border-color: var(--color-disabled-text);
  color: var(--color-disabled-text);
  box-shadow: 0 4px 0 #120e18;
  cursor: not-allowed;
  transform: none;
}

.btn-title {
  font-size: 18px;
  font-weight: bold;
}

.btn-meta {
  font-size: 13px;
}

.inventory-info {
  text-align: center;
  font-size: 14px;
  color: var(--color-muted);
}

.inventory-info strong {
  color: var(--color-gold);
}

@media (max-width: 360px) {
  .miner-card {
    padding: 16px;
  }
  .stat-value {
    font-size: 18px;
  }
  .pixel-btn {
    padding: 10px 12px;
  }
}

(function () {
  "use strict";

  const DRILL_COST = 10;
  let gold = 0;
  let drills = 0;

  const goldCountEl = document.getElementById("gold-count");
  const goldRateEl = document.getElementById("gold-rate");
  const drillCountEl = document.getElementById("drill-count");
  const buyDrillBtn = document.getElementById("buy-drill-btn");
  const canvas = document.getElementById("mine-canvas");
  const ctx = canvas.getContext("2d");

  function getGoldPerSecond() {
    return 1 + drills;
  }

  function updateUI() {
    goldCountEl.textContent = gold.toString();
    goldRateEl.textContent = getGoldPerSecond().toString();
    drillCountEl.textContent = drills.toString();
    buyDrillBtn.disabled = gold < DRILL_COST;
  }

  function buyDrill() {
    if (gold >= DRILL_COST) {
      gold -= DRILL_COST;
      drills += 1;
      updateUI();
      drawScene();
    }
  }

  function tick() {
    gold += getGoldPerSecond();
    updateUI();
  }

  buyDrillBtn.addEventListener("click", buyDrill);

  // Pixel animation/rendering logic
  let animFrame = 0;
  function drawScene() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Ground line
    ctx.fillStyle = "#4d3b66";
    ctx.fillRect(0, 95, canvas.width, 4);

    // Gold vein / Rock
    ctx.fillStyle = "#3a2b4c";
    ctx.fillRect(200, 45, 55, 50);
    ctx.fillStyle = "#ffbe2e";
    ctx.fillRect(210, 55, 8, 8);
    ctx.fillRect(230, 65, 10, 10);
    ctx.fillRect(220, 80, 8, 8);

    // Miner Cart
    ctx.fillStyle = "#8a6d46";
    ctx.fillRect(30, 60, 45, 30);
    ctx.fillStyle = "#ffbe2e";
    ctx.fillRect(35, 52, 35, 8);

    // Wheels
    ctx.fillStyle = "#150f1d";
    ctx.fillRect(35, 90, 10, 8);
    ctx.fillRect(60, 90, 10, 8);

    // Drills rendering
    const activeDrillsCount = Math.min(drills, 3);
    for (let i = 0; i < activeDrillsCount; i++) {
      const x = 110 + i * 28;
      const bounce = (animFrame % 2 === 0 && i % 2 === 0) ? 2 : 0;
      ctx.fillStyle = "#ab9cb8";
      ctx.fillRect(x, 65 + bounce, 12, 28);
      ctx.fillStyle = "#ffbe2e";
      ctx.fillRect(x + 2, 85 + bounce, 8, 10);
    }
  }

  function renderLoop() {
    animFrame++;
    drawScene();
    requestAnimationFrame(renderLoop);
  }

  updateUI();
  setInterval(tick, 1000);
  requestAnimationFrame(renderLoop);
})();
